    trapExamples: [{ question: "午前9時から 午後3時までは 何時間？", wrongAnswer: "12時間", trapExplanation: "時間の さを 3−9 の ように 計算して しまった。", correctAnswer: "6時間", correctExplanation: "午前9時→正午で 3時間、正午→午後3時で 3時間。あわせて 6時間。" }],
